  "findings": [
    {
      "check_id": "UNKNOWN",
      "title": "Router connected directly to the global network",
      "resource": "nifcloud_router.negative",
      "severity": "HIGH",
      "explanation": "The router interface is attached to net-COMMON_GLOBAL, which exposes it to the public NIFCLOUD network and increases its externally reachable attack surface. Attaching it to the common private network avoids direct public connectivity."
    }
  ],
  "patched_code": "resource \"nifcloud_router\" \"negative\" {\n  security_group = nifcloud_security_group.router.group_name\n\n  network_interface {\n    network_id = \"net-COMMON_PRIVATE\"\n  }\n}\n",
  "fix_summary": "Changed the router interface from the public common global network to the common private network while retaining the existing security group association."
}
